/* Post-battle settlement uses actual crews and recorded rewards, once per session. */
(()=>{'use strict';
const A=()=>window.MMCampaignAutomation,E=x=>esc(String(x??'')),T=(en,ko)=>window.UKI18n?.language==='en'?en:ko,L=(en,ko)=>`<span data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(T(en,ko))}</span>`,clone=x=>structuredClone(x);
const source=id=>(window.RULES_DATA?.coreRules||[]).find(r=>r.id===id&&r.source_verified),get=(c,sid)=>(c.sessions||[]).find(s=>s.id===sid),gangs=()=>data.gangs;
const positive=(x,name)=>{const n=Number(x??0);if(!Number.isSafeInteger(n)||n<0)throw Error(name+' must be a non-negative integer');return n;};
const integer=(x,name)=>{const n=Number(x??0);if(!Number.isSafeInteger(n))throw Error(name+' must be an integer');return n;};
function eligible(f,g){const t=window.MMVerifiedRules?.modelType(f,g);return !!t?.source_verified&&Number.isFinite(t.starting_xp)&&t.no_xp!==true&&t.rule_data?.xp_eligible!==false&&t.rule_data?.gain_xp!==false;}
const recorded=(f,s)=>(f.xpHistory||[]).some(x=>x.sessionId===s.id&&Number(x.events?.participation)>0);
function crew(c,s,p,pool=gangs()){const g=pool.find(g=>g.id===p.gangId);return [...new Map((p.crew||[]).map(r=>[r.fighterId,r])).values()].map(row=>({row,g,f:[...(g?.fighters||[]),...(g?.vehicles||[])].find(f=>f.id===row.fighterId)})).filter(x=>x.f);}
function automaticParticipation(c,s,pool=gangs()){return (s.participants||[]).flatMap(p=>crew(c,s,p,pool).filter(x=>eligible(x.f,x.g)&&!recorded(x.f,s)).map(x=>({...x,p,key:p.id+'|'+x.f.id})));}
function rescues(c,s,pool=gangs()){const ids=(s.participants||[]).map(p=>p.gangId);return(window.MMCampaignOperations?.captureRows(c,pool)||[]).filter(r=>r.fighter&&ids.includes(r.holder.id)&&ids.includes(r.source?.id)&&r.holder.id!==r.source.id);}
function preview(c,s,input,pool=gangs()){
 if(!s||!['battle','post-battle'].includes(s.stage)||s.status==='Completed'||s.rewardsApplied||(c.battles||[]).some(b=>b.sessionId===s.id&&['Played','Completed'].includes(b.status)))throw Error(T('This session has already been settled or is not in battle.','이미 정산했거나 전투가 시작되지 않은 전투입니다.'));
 const parts=s.participants||[],ids=parts.map(p=>p.gangId);if(parts.length<2||new Set(ids).size!==ids.length||ids.some(id=>!c.members?.some(m=>m.gangId===id)||!pool.some(g=>g.id===id)))throw Error('Choose different enrolled gangs');
 const winner=input.winner==='draw'?'':input.winner;if(winner&&!ids.includes(winner)||!winner&&input.winner!=='draw')throw Error(T('Choose a participating winner or a draw.','참가 갱의 승리 또는 무승부를 선택하세요.'));
 const phase=s.campaignPhase||(c.automation?.challenges||[]).find(x=>x.id===s.challengeId)?.phase||A().phase(c),territory=(c.territories||[]).find(t=>t.id===s.territoryId);let transfer=null;
 if(s.territoryId){if(!territory||!window.MMCampaignChallenges?.canStake(territory)||!['Occupation','Takeover'].includes(phase))throw Error(T('Review the stake and original campaign phase before settlement.','정산 전에 걸린 영토와 전투 당시 단계를 확인하세요.'));const ch=(c.automation?.challenges||[]).find(x=>x.id===s.challengeId),previous=territory.gangId||territory.gang_id||'';if(ch&&ch.stakeOwnerBefore!==undefined&&ch.stakeOwnerBefore!==previous)throw Error(T('The staked territory changed owner. Review the conflict first.','걸린 영토 소유자가 바뀌었습니다. 충돌을 먼저 확인하세요.'));if(winner&&winner!==previous)transfer={territoryId:territory.id,fromGangId:previous,toGangId:winner};}
 const event=source('n26-core-xp-events')?.rule_data?.events?.find(e=>e.key==='participation');if(!event)throw Error('Verified participation XP is unavailable');
 const all=parts.flatMap(p=>crew(c,s,p,pool).map(x=>({...x,p,key:p.id+'|'+x.f.id}))),selected=new Set(input.participation===undefined?automaticParticipation(c,s,pool).map(x=>x.key):input.participation||[]);if([...selected].some(k=>!all.some(x=>x.key===k)))throw Error('Participation contains a model outside the deployed crew');
 const awards=all.filter(x=>selected.has(x.key)).map(x=>{if(!eligible(x.f,x.g)||recorded(x.f,s))throw Error('Participation award changed; reopen the preview');positive(Number(x.f.xp||0)+event.xp,'XP');return{gangId:x.g.id,fighterId:x.f.id,participantId:x.p.id,amount:event.xp,name:x.f.name};});
 const rewards=parts.map(p=>{const g=pool.find(g=>g.id===p.gangId),creditChange=integer(p.creditsEarned,'Recorded credits'),reputationChange=integer(p.reputationChange,'Recorded reputation'),resources=Object.entries(p.resources||{}).map(([id,delta])=>{if(!(c.resources||[]).some(r=>r.id===id))throw Error('Unknown campaign resource');const m=c.members.find(m=>m.gangId===g.id),amount=integer(m.resources?.[id]||0,'Resource')+integer(delta,'Resource delta');if(amount<0)throw Error('Insufficient campaign resources');return{id,amount};});return{gangId:g.id,creditChange,reputationChange,credits:Math.max(0,positive(g.credits,'Credits')+creditChange),reputation:Math.max(0,positive(g.reputation,'Reputation')+reputationChange),resources};});
 if(transfer&&phase==='Takeover'&&transfer.fromGangId){const loss=source('official-003-core-takeover-phase-rewards')?.rule_data?.territory_loss_reputation;if(loss!==-1)throw Error('Verified Takeover reputation loss is unavailable');const reward=rewards.find(r=>r.gangId===transfer.fromGangId);if(!reward)throw Error('The former territory owner must be a battle participant');reward.reputation=Math.max(0,reward.reputation+loss);reward.reputationChange+=loss;}
 for(const r of rewards)if(!Number.isSafeInteger(r.credits)||!Number.isSafeInteger(r.reputation))throw Error('Reward total exceeds the supported range');
 const available=rescues(c,s,pool),rescueIds=new Set(input.rescues||[]);if([...rescueIds].some(id=>!available.some(r=>r.record.id===id&&r.source.id===winner)))throw Error(T('Only a winning source gang can record an actually completed rescue.','구출하려는 파이터의 갱이 승리했고, 구출 조건까지 충족한 파이터만 선택하세요.'));
 return{winner,isDraw:!winner,phase,transfer,awards,rewards,rescueResults:available.filter(r=>rescueIds.has(r.record.id)).map(r=>({captureId:r.record.id,fighterId:r.fighter.id,rescued:true})),event};
}
function settleDraft(c,s,input,pool){const plan=preview(c,s,input,pool),at=new Date().toISOString();
 for(const reward of plan.rewards){const g=pool.find(g=>g.id===reward.gangId);g.credits=reward.credits;g.reputation=reward.reputation;const member=c.members.find(m=>m.gangId===g.id);if(reward.resources.length){member.resources??={};for(const r of reward.resources)member.resources[r.id]=r.amount;}}
 for(const a of plan.awards){const g=pool.find(g=>g.id===a.gangId),p=s.participants.find(p=>p.id===a.participantId),row=p.crew.find(r=>r.fighterId===a.fighterId),f=[...(g.fighters||[]),...(g.vehicles||[])].find(f=>f.id===a.fighterId);f.xp=Number(f.xp||0)+a.amount;row.xpEarned=Number(row.xpEarned||0)+a.amount;(f.xpHistory??=[]).unshift({id:id(),at,amount:a.amount,reason:plan.event.label,events:{participation:1},sessionId:s.id,edition:g.edition});}
 if(plan.transfer){const t=c.territories.find(t=>t.id===plan.transfer.territoryId);t.gangId=plan.transfer.toGangId;if(Object.hasOwn(t,'gang_id'))t.gang_id=t.gangId;}
 const winners=plan.winner?[plan.winner]:[];Object.assign(s,{status:'Completed',stage:'completed',winners,winner:plan.winner,isDraw:plan.isDraw,rewardsApplied:true,settledAt:at,cycle:s.cycle||A().cycle(c),rescueResults:plan.rescueResults});
 const value={id:id(),sessionId:s.id,challengeId:s.challengeId||null,name:s.scenario||T('Campaign battle','캠페인 전투'),date:s.date||at.slice(0,10),cycle:s.cycle,participants:s.participants.map(p=>({gangId:p.gangId,gang_id:p.gangId,role:p.role,isWinner:winners.includes(p.gangId)})),attacker:s.participants.find(p=>p.role==='attacker')?.gangId||s.challenger,defender:s.participants.find(p=>p.role==='defender')?.gangId||s.opponent,winners,winner:plan.winner,isDraw:plan.isDraw,territoryId:s.territoryId||'',claimedByGangId:plan.winner,notes:s.notes||'',status:'Played',deployment:s.deployment,objective:s.objective,crewSelection:s.crewSelection,rescueResults:clone(plan.rescueResults),automationSettlement:{at,rewards:clone(plan.rewards),xp:clone(plan.awards),territoryTransfer:plan.transfer}};
 (c.battles??=[]).push(value);const ch=(c.automation?.challenges||[]).find(x=>x.id===s.challengeId);if(ch){ch.status='played';ch.completedAt=at;ch.battleId=value.id;if(ch.legacyBattleId){const legacy=c.battles.find(b=>b.id===ch.legacyBattleId);if(legacy)Object.assign(legacy,{status:'Played',winners,winner:plan.winner,sessionId:s.id});}}
 (c.activity??=[]).unshift({id:id(),at,text:T('Battle result settled once','전투 결과 정산 완료')});return plan;
}
async function settle(c,sid,input){if(!A().canEdit(c))throw Error('Campaign editor access required');const s=get(c,sid);const ids=[...new Set((s?.participants||[]).map(p=>p.gangId))];preview(c,s,input);return A().apply(c,{key:'battle-settle:'+sid,label:T('Settle battle result','전투 결과 일괄 정산'),gangIds:ids,mutate:d=>settleDraft(d.campaign,get(d.campaign,sid),input,d.gangs)});}
function show(c,sid){
 const s=get(c,sid);if(!s||!A().canEdit(c)||s.status==='Completed'||s.rewardsApplied)return;
 const options=(s.participants||[]).map(p=>({p,g:gangs().find(g=>g.id===p.gangId)})),captives=rescues(c,s),models=automaticParticipation(c,s),event=source('n26-core-xp-events')?.rule_data?.events?.find(e=>e.key==='participation');
 const existing=s.isDraw===true?'draw':options.some(x=>x.g?.id===s.winner)?s.winner:s.winners?.length===1&&options.some(x=>x.g?.id===s.winners[0])?s.winners[0]:'';
 const signed=n=>Number(n)>0?'+'+n:String(n||0);
 function summary(plan){return options.map(({p,g})=>{const awards=plan?plan.awards.filter(a=>a.participantId===p.id):models.filter(x=>x.p.id===p.id),reward=plan?.rewards.find(r=>r.gangId===g.id),resources=Object.entries(p.resources||{}).filter(([,n])=>Number(n)!==0);return `<article><strong data-user-text>${E(g.name)}</strong><dl><div><dt>${L('Participation XP','참가 XP')}</dt><dd>${awards.length} ${L('fighters','명')} · +${awards.reduce((n,a)=>n+(a.amount??event?.xp??0),0)} XP</dd></div><div><dt>${L('Credits','크레딧')}</dt><dd>${E(signed(reward?.creditChange??p.creditsEarned))}</dd></div><div><dt>${L('Reputation','명성')}</dt><dd>${E(signed(reward?.reputationChange??p.reputationChange))}</dd></div>${resources.map(([key,n])=>`<div><dt data-user-text>${E(c.resources?.find(r=>r.id===key)?.name||key)}</dt><dd>${E(signed(n))}</dd></div>`).join('')}</dl></article>`;}).join('');}
 A().modal(T('Settle battle result','전투 결과 일괄 정산'),`<label class="wide">${L('Battle result','전투 결과')}<select name="winner" required><option value="">${T('Choose result','결과 선택')}</option>${options.map(({g})=>`<option value="${E(g.id)}">${E(g.name)} ${T('wins','승리')}</option>`).join('')}<option value="draw">${T('Draw','무승부')}</option></select></label><p class="wide ca-settlement-intro">${L('Participation XP, recorded rewards and territory changes are applied together. Previously awarded participation XP and undeployed reserves are excluded automatically.','참가 XP·기록된 보상·영토 변경을 한 번에 적용합니다. 이미 받은 참가 XP와 미투입 증원은 자동 제외합니다.')}</p><div class="wide ca-result-summary ca-batch-summary" data-ca-result-summary>${summary()}</div>${captives.length?`<fieldset class="wide"><legend>${L('Completed rescue objectives','완료한 구출 목표')}</legend><p>${L('Only select captives whose rescue objective was achieved by the winning gang.','승리한 갱이 구출 목표까지 달성한 파이터만 선택하세요.')}</p>${captives.map((x,i)=>`<label class="checkline"><input type="checkbox" name="rescue${i}" value="yes"><span data-user-text>${E(x.source.name)} / ${E(x.fighter.name)}</span></label>`).join('')}</fieldset>`:''}<div class="wide ca-preview" data-ca-result-preview role="status" aria-live="polite"></div>`,T('Apply all results','전투 결과 한 번에 적용'),()=>settle(c,sid,read()));
 const f=document.querySelector('#modal-form'),submit=document.querySelector('#modal-submit');f.closest('.modal')?.classList.add('ca-batch-settlement');f.elements.winner.value=existing;
 function read(){return{winner:f.elements.winner.value,rescues:captives.filter((_,i)=>f.elements['rescue'+i]?.checked).map(x=>x.record.id)};}
 function update(){const box=f.querySelector('[data-ca-result-preview]');if(!f.elements.winner.value){box.textContent=T('Choose the result, then apply everything once.','전투 결과를 선택하면 한 번에 적용할 수 있습니다.');box.classList.remove('is-error');submit.disabled=true;return;}
  try{const plan=preview(c,s,read());f.querySelector('[data-ca-result-summary]').innerHTML=summary(plan);box.textContent=`${T('Territory','영토')}: ${plan.transfer?(c.territories.find(t=>t.id===plan.transfer.territoryId)?.name+' → '+gangs().find(g=>g.id===plan.transfer.toGangId)?.name):T('Retained','변경 없음')}${captives.length?' · '+T('Rescues','구출')+': '+plan.rescueResults.length:''}`;box.classList.remove('is-error');submit.disabled=false;}
  catch(error){box.textContent=error.message;box.classList.add('is-error');submit.disabled=true;}
 }
 f.addEventListener('change',update);update();
}
const shared=c=>!!(c.remoteOwnerId||c.remoteCampaignId||c.remoteRevision);
function resultContext(s,p,row){
 const c=typeof campaign==='function'&&campaign();if(!c||c.edition!=='N26'||!canSettle(c,s)||!['battle','post-battle'].includes(s.stage))return {};
 const g=gangs().find(g=>g.id===p.gangId),f=g?.fighters?.find(f=>f.id===row.fighterId);if(!f)return {};
 const fingerprint=JSON.stringify([f,row]),owner=window.AccountParity?.account?.id||'',operation='battle-result:'+s.id+':'+id(),stage=s.stage;
 return{autoParticipation:true,...(shared(c)?{commit:(mutate,label)=>{
  if(!A().canEdit(c)||get(c,s.id)!==s||!s.participants.includes(p)||!p.crew.includes(row)||s.stage!==stage||(window.AccountParity?.account?.id||'')!==owner)throw Error(T('The record or your access changed. Reopen the result.','기록이나 접근 권한이 변경되었습니다. 결과 입력 창을 다시 여세요.'));
  return A().apply(c,{key:operation,label,gangIds:[g.id],mutate:d=>{const ds=get(d.campaign,s.id),dg=d.gangs.find(g=>g.id===p.gangId),dr=ds?.participants?.find(x=>x.id===p.id)?.crew?.find(x=>x.fighterId===row.fighterId),df=dg?.fighters?.find(x=>x.id===row.fighterId);if(ds?.stage!==stage||JSON.stringify([df,dr])!==fingerprint)throw Error(T('The fighter changed. Reopen the result.','파이터 기록이 변경되었습니다. 결과 입력 창을 다시 여세요.'));return mutate(df,dg,dr);}});
 }}:{})};
}
function updateResource(c,s,p,key,value){
 if(!shared(c)||!canSettle(c,s)||!['battle','post-battle'].includes(s.stage))return null;
 if(!A().canEdit(c))throw Error('Campaign editor access required');const number=integer(value,'Reward');if(!['creditsEarned','reputationChange'].includes(key)&&!c.resources?.some(r=>r.id===key))throw Error('Unknown campaign resource');
 if(Number((['creditsEarned','reputationChange'].includes(key)?p[key]:p.resources?.[key])||0)===number)return Promise.resolve();
 return A().apply(c,{key:'battle-reward:'+s.id+':'+id(),label:T('Record battle reward','전투 보상 입력'),gangIds:[],mutate:d=>{const ds=get(d.campaign,s.id),dp=ds?.participants.find(x=>x.id===p.id);if(!dp||!['battle','post-battle'].includes(ds.stage))throw Error('Battle result is no longer editable');if(['creditsEarned','reputationChange'].includes(key))dp[key]=number;else{dp.resources??={};dp.resources[key]=number;}}});
}
function reserveControl(c,s,p){return canSettle(c,s)&&['battle','post-battle'].includes(s.stage)&&p.reinforcements?.length?A().button('battle','deployed','Record deployed reserves','출전 증원 반영',`data-ca-id="${E(s.id)}" data-ca-participant="${E(p.id)}" ${A().canEdit(c)?'':'disabled'}`,'small'):'';}
function deployed(c,sid,pid){const s=get(c,sid),p=s?.participants.find(p=>p.id===pid);if(!A().canEdit(c)||!p||!['battle','post-battle'].includes(s.stage))return;
 const g=gangs().find(g=>g.id===p.gangId),reserves=p.reinforcements||[],operation='battle-deployment:'+sid+':'+id();
 A().modal(T('Record deployed reserves','출전 증원 반영'),`<p class="wide">${L('Select reserves that actually entered the battlefield. They receive participation XP together with the starting crew when you settle the result.','실제로 전장에 투입된 증원만 선택하세요. 결과 확정 시 시작 크루와 함께 참가 XP가 적용됩니다.')}</p>${reserves.map((r,i)=>`<label class="checkline wide"><input type="checkbox" name="deployed${i}" value="yes"><span data-user-text>${E(g?.fighters?.find(f=>f.id===r.fighterId)?.name||r.fighterId)}</span></label>`).join('')}`,T('Record deployment','출전 명단에 반영'),v=>{const ids=reserves.filter((_,i)=>v['deployed'+i]==='yes').map(r=>r.fighterId);if(!ids.length)return true;return A().apply(c,{key:operation,label:T('Record deployed reserves','출전 증원 반영'),gangIds:[],mutate:d=>{const ds=get(d.campaign,sid),dp=ds?.participants.find(p=>p.id===pid);if(!dp||!['battle','post-battle'].includes(ds.stage)||ids.some(fid=>!dp.reinforcements?.some(r=>r.fighterId===fid)||dp.crew.some(r=>r.fighterId===fid)))throw Error('The deployed crew changed; reopen the result');dp.crew.push(...dp.reinforcements.filter(r=>ids.includes(r.fighterId)));dp.reinforcements=dp.reinforcements.filter(r=>!ids.includes(r.fighterId));}});});
}
function updateSideJob(c,s,p,completed){if(!shared(c)||!canSettle(c,s))return null;return A().apply(c,{key:'battle-sidejob:'+s.id+':'+id(),label:T('Record Side Job result','사이드 잡 결과 반영'),gangIds:[],mutate:d=>{const ds=get(d.campaign,s.id),dp=ds?.participants.find(x=>x.id===p.id);if(!dp||!['battle','post-battle'].includes(ds.stage))throw Error('Battle result is no longer editable');dp.sideJobCompleted=completed;if(Object.hasOwn(dp,'side_job_completed'))dp.side_job_completed=completed;}});}
const btn=(action,en,ko,s,disabled=false)=>A().button('battle',action,en,ko,`data-ca-id="${E(s.id)}" ${disabled?'disabled':''}`,'primary');
function canSettle(c,s){return c?.edition==='N26'&&s?.participants?.length===2&&(!s?.territoryId||['Occupation','Takeover'].includes(s.campaignPhase||(c.automation?.challenges||[]).find(x=>x.id===s.challengeId)?.phase||A().phase(c)));}
function resultControl(c,s){if(!canSettle(c,s))return '';return ['battle','post-battle'].includes(s.stage)?btn('settle','Settle battle result','전투 결과 일괄 정산',s,!A().canEdit(c)):'';}
function render(c){return window.MMCampaignPreparation?.render(c)||'';}
function handle(action,c,d){if(action==='deployed')return deployed(c,d.caId,d.caParticipant);if(action==='settle')return show(c,d.caId);if(action==='open'){const s=get(c,d.caId);if(s)sessionDetail(s);}}
window.MMCampaignBattle={render,handle,resultControl,canSettle,preview,settleDraft,settle,show,eligible,recorded,crew,rescues,automaticParticipation,resultContext,updateResource,reserveControl,deployed,updateSideJob};
const previousComplete=completeSession;completeSession=function(s){const c=campaign();if(canSettle(c,s))return show(c,s.id);return previousComplete(s);};
const previousPage=cpSessionPage;cpSessionPage=function(c){const html=previousPage(c),s=get(c,data.selectedBattleSession);if(!s||c.edition!=='N26')return html;const extra=['pre-battle','battle','post-battle'].includes(s.stage)?window.MMCampaignPreparation?.sessionControls?.(c,s)||resultControl(c,s):'';return html.replace('<div class="stack">','<div class="stack">'+(extra?'<section class="card ca-session-tools"><div>'+extra+'</div></section>':''));};
})();
